                return '<defs><pattern id="' + id + '" patternUnits="userSpaceOnUse" width="10" height="12"><path d="M2 0L7 6L2 12" fill="none" stroke="#ffffff" stroke-width="2" stroke-opacity="0.35"/></pattern></defs>' +
                    line(d, c[1], w) + line(d, 'url(#' + id + ')', w);
