    chip.title = (chip.getAttribute('data-dc') || '') + ' rolled ' + rolls.join(' + ') + (rolls.length > 1 ? ' = ' + total : '') + ' (click to roll again!)';
    const sides = parseInt((chip.getAttribute('data-dc') || '1d20').split('d')[1], 10) || 20;
