    const HL_BUILTINS = ('pow min max random randint clamp str num len range push pop remove join split upper lower contains keys time print renderRT hover effect_size skill btn remvar key beep stop floor ceil round abs sqrt sin cos tan atan2 PI inherit textbox counter beepbox annotate_highlight annotate_underline annotate_strikethrough annotate_box annotate_halo annotate_brackets annotate_spotlight annotate_accent annotate_bubble annotate_dusk annotate_prism annotate_complement annotate_ticket annotate_neon annotate_stamp annotate_tape annotate_checker annotate_halftone annotate_aurora annotate_mild annotate_wrap annotate_belt annotate_bucket annotate_torpedo annotate_bottle annotate_packet annotate_select annotate_capsule annotate_frost annotate_pixel annotate_flag annotate_gem lua mat_match mat_has mat_keys renderPT python sql sql_save sql_load lam vec mat dot cross norm normalize det transpose inverse identity zeros trace rows cols to_list ls_set ls_get ls_remove ls_keys ls_clear to_json from_json export_file import_file regex_test regex_match regex_all regex_replace regex_split effect effect_saturation effect_brightness effect_contrast effect_grayscale effect_sepia effect_invert effect_hue effect_blur effect_opacity effect_shadow effect_tint').split(' ');
