            last = m.index + m[0].length;
            let c = '';
            if (m[1]) c = 'c'; else if (m[3]) c = 'k'; /* the mouse operator "> and the matcher arrow ~> */ else if (m[2] || m[4]) c = 's'; else if (m[5]) c = 'n';
