        s = s.replace(/\[(__|##)(\d{1,2})?(?:\|([^\]\n]*))?\]/g, (_, kind, w, ans) => stash('<span class="kd-fill' + (kind === '##' ? ' kd-fill-box' : '') + '" data-w="' + (w || 6) + '"' + (ans ? ' data-answer="' + esc(ans) + '"' : '') + ' style="--w:' + (w || 6) + '" contenteditable="false"></span>'));
