        if ((m = /^(\s*)<pic\s+(\S+)(?:\s+(.*))?>\s*$/.exec(l))) return m[1] + '![' + (m[3] || '') + '](' + m[2] + ')';
        // a table: [= Lane | Time =] is the header row (a separator line follows it), [ 1 | 52 ] is a row
