        if ((m = /^(\s*)>>\s(.*)$/.exec(l))) return m[1] + '<> ' + m[2];
        if ((m = /^(\s*)>\s(.*)$/.exec(l))) return m[1] + '<< ' + m[2];
        if ((m = /^(\s*)%>\s(.*)$/.exec(l))) return m[1] + '<: ' + m[2];
        if ((m = new RegExp('^(\\s*)([' + QUOTE_MARKS + '])>\\s(.*)$').exec(l))) return m[1] + '<' + m[2] + ' ' + m[3];
        if ((m = /^(\s*)([-+.~=*])\s(.*)$/.exec(l))) return m[1] + '(' + (m[2] === '-' ? '' : m[2]) + ') ' + m[3];
