        if ((m = /^(\s*)::blank\{([^}]*)\}\s*$/.exec(l))) return m[1] + '(_ ' + m[2] + ' _)';
        if ((m = /^(\s*)!\[([^\]\n]*)\]\((https:\/\/[^)\s]+)\)\s*$/.exec(l))) return m[1] + '<pic ' + m[3] + (m[2] ? ' ' + m[2] : '') + '>';
