        if ((m = /^counter\s+([A-Za-z_]\w*)(?:\s*=\s*(-?\d+(?:\.\d+)?))?(?:\s+step\s+(\d+(?:\.\d+)?))?$/.exec(s))) return { kind: 'counter', name: m[1], value: m[2] ? parseFloat(m[2]) : 0, step: m[3] ? parseFloat(m[3]) : 1 };
