        if ((m = /^(\d+(?:\.\d+)?)\s*(s|sec|m|min|h)?$/i.exec(s))) { const v = parseFloat(m[1]), u = (m[2] || 'm').toLowerCase(); return Math.round(u[0] === 's' ? v : u[0] === 'h' ? v * 3600 : v * 60); }
